from typing import List

def isEulerCircuit(V: int, adj: List[List[int]]) -> int:
    def dfs(v: int, visited: List[bool]) -> None:
        visited[v] = True
        for neighbor in adj[v]:
            if not visited[neighbor]:
                dfs(neighbor, visited)

    visited = [False] * V
    start_vertex = -1
    odd_degree_count = 0

    for i in range(V):
        degree = len(adj[i])
        if degree > 0:
            start_vertex = i
        if degree % 2 != 0:
            odd_degree_count += 1

    if odd_degree_count > 2:
        return 0

    dfs(start_vertex, visited)

    for i in range(V):
        if adj[i] and not visited[i]:
            return 0

    if odd_degree_count == 0:
        return 2
    elif odd_degree_count == 2:
        return 1
    return 0
